n = int(input())
price = {}
stock = {}
sold = {}
for _ in range(n):
    a, b, c = input().split()
    price[a] = int(b)
    stock[a] = int(c)
money = int(input())
while True:
    line = input().split()
    if line[0] == "끝":
        break
    menu, k = line[0], int(line[1])
    if menu not in price:
        print("없는 메뉴")
    elif stock[menu] < k:
        print(f"재고 부족 (남은 재고 {stock[menu]})")
    elif money < price[menu] * k:
        print(f"잔액 부족 ({price[menu] * k - money}원 부족)")
    else:
        stock[menu] -= k
        money -= price[menu] * k
        sold[menu] = sold.get(menu, 0) + k
        print(f"주문 완료: {menu} x{k}")
for m in price:
    if m in sold:
        print(m, sold[m])
print(f"남은 돈 {money}원")
